import numpy as np
from scipy.spatial.transform import Rotation as R

def setup(s):
    global S
    S=s

def pose():
    d=S.data; site=S.env.robots[0].eef_site_id['right']
    return d.site_xpos[site].copy(), d.site_xmat[site].reshape(3,3).copy()

def body(name):
    return S.data.xpos[S.model.body(name).id].copy()

def geom(name):
    return S.data.geom_xpos[S.model.geom(name).id].copy()

def status():
    print('step',len(S.actions),'eef',pose()[0].round(4),'obj',body('obj_main').round(4),'door',door(),'on',S.env.microwave.get_state(),flush=True)

def door():
    return S.data.qpos[S.model.joint('microwave_right_group_microjoint').qposadr[0]]

def command(p=None, ori=None, grip=-1, base=None, torso=0, mode=-1, speed=.012, rspeed=.09):
    c=S.env.robots[0].part_controllers['right']
    bp=S.data.xpos[S.model.body('robot0_link0').id]
    br=S.data.xmat[S.model.body('robot0_link0').id].reshape(3,3)
    actual, ar=pose()
    if c._goal_update_mode=='desired' and c.goal_pos is not None:
        cp=br@c.goal_pos+bp
        cr=br@c.goal_ori
    else:
        cp,cr=actual,ar
    a=np.zeros(12); a[6]=grip; a[10]=torso; a[11]=mode
    if p is not None:
        delta=br.T@(np.asarray(p)-cp)
        norm=np.linalg.norm(delta)
        if norm>speed: delta*=speed/norm
        a[:3]=delta/.05
    if ori is not None:
        dr=R.from_matrix(br.T@np.asarray(ori)@cr.T@br).as_rotvec()
        norm=np.linalg.norm(dr)
        if norm>rspeed: dr*=rspeed/norm
        a[3:6]=dr/.5
    if base is not None: a[7:10]=base
    S.step(a)

def move(p, ori=None, grip=-1, n=100, tol=.008, speed=.012, rspeed=.09, torso=0):
    for i in range(n):
        command(p,ori,grip,torso=torso,speed=speed,rspeed=rspeed)
        cp,cr=pose()
        if np.linalg.norm(cp-p)<tol and (ori is None or np.linalg.norm(R.from_matrix(ori@cr.T).as_rotvec())<.07) and i>8:
            break
    print('move',i+1, 'err',np.round(cp-p,4),flush=True)

def hold(n=10,grip=-1,p=None,ori=None):
    for _ in range(n): command(p,ori,grip)

DOWN=np.diag([1,-1,-1])
FRONT=np.array([[0,0,1],[0,-1,0],[1,0,0]])
PY"}));
